diff --git a/app/Services/BillingGateway.php b/app/Services/BillingGateway.php
index 646ed8d..62d67de 100755
--- a/app/Services/BillingGateway.php
+++ b/app/Services/BillingGateway.php
@@ -11,7 +11,13 @@ class BillingGateway

     public function __construct()
     {
-        $this->apiKey = env('PAYRAIL_API_KEY', 'sandbox-key');
+        $apiKey = config('services.billing.key');
+
+        if (! is_string($apiKey) || trim($apiKey) === '') {
+            throw new \RuntimeException('BillingHub API key is not configured.');
+        }
+
+        $this->apiKey = $apiKey;
     }

     /**
diff --git a/config/services.php b/config/services.php
new file mode 100644
index 0000000..9430249
--- /dev/null
+++ b/config/services.php
@@ -0,0 +1,7 @@
+<?php
+
+return [
+    'billing' => [
+        'key' => env('PAYRAIL_API_KEY'),
+    ],
+];
